-- A source row can describe several strengths or alternative products. Preserve it
-- separately until staff supply an exact sellable/stock unit and price.
create table public.catalog_source_items (
 id uuid primary key,
 source_tab text not null,
 source_row integer not null check(source_row > 1),
 name text not null check(length(trim(name)) between 1 and 200),
 source_fields jsonb not null check(jsonb_typeof(source_fields)='object'),
 source_url text not null default 'https://docs.google.com/spreadsheets/d/1O1FTZ8fjYHwyMt01I8DAyHjm-iCDfOtL7k44dSaDP6Q/edit',
 captured_on date not null default '2026-11-10',
 unique(source_tab,source_row)
);
create table public.catalog_source_products (
 id uuid primary key default gen_random_uuid(),
 source_id uuid not null references public.catalog_source_items(id) on delete restrict,
 product_id uuid not null references public.catalog_products(id) on delete restrict,
 created_by uuid not null references auth.users(id),
 created_at timestamptz not null default now(),
 unique(source_id,product_id)
);
alter table public.catalog_source_items enable row level security;
alter table public.catalog_source_products enable row level security;
revoke all on public.catalog_source_items,public.catalog_source_products from public,anon,authenticated,service_role;
grant select on public.catalog_source_items,public.catalog_source_products to authenticated,service_role;
create policy "Active staff read source catalog" on public.catalog_source_items for select to authenticated using(public.is_active_staff(auth.uid()));
create policy "Active staff read source products" on public.catalog_source_products for select to authenticated using(public.is_active_staff(auth.uid()));
create trigger catalog_source_products_audit after insert on public.catalog_source_products for each row execute function public.audit_trigger_fn();

create function public.search_catalog_source_items(p_search text default '') returns jsonb
language plpgsql security definer set search_path=public as $$
begin
 perform public.clinical_require_staff();
 if length(p_search)>200 then raise exception 'Search is too long' using errcode='23514';end if;
 return coalesce((select jsonb_agg(to_jsonb(s)||jsonb_build_object('products',
  coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'active',p.active) order by p.name,p.id)
   from public.catalog_source_products l join public.catalog_products p on p.id=l.product_id where l.source_id=s.id),'[]'::jsonb)) order by s.source_tab,s.source_row)
  from public.catalog_source_items s where strpos(lower(s.name||' '||s.source_tab||' '||s.source_fields::text),lower(coalesce(p_search,'')))>0),'[]'::jsonb);
end $$;

create function public.configure_catalog_source_item(
 p_actor_id uuid,p_source_id uuid,p_id uuid,p_name text,p_kind text,
 p_manufacturer text,p_unit text,p_unit_price_cents bigint
) returns public.catalog_products
language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff(); result public.catalog_products;
begin
 if p_actor_id is distinct from actor then raise exception 'Staff session changed' using errcode='42501';end if;
 perform 1 from public.catalog_source_items where id=p_source_id for share;
 if not found then raise exception 'Source catalog row not found' using errcode='23514';end if;
 -- Calls the existing audited creator; exact UUID/payload retry is idempotent.
 result:=public.create_inventory_product(p_id,p_name,p_kind,p_manufacturer,p_unit,p_unit_price_cents);
 insert into public.catalog_source_products(source_id,product_id,created_by) values(p_source_id,result.id,actor) on conflict do nothing;
 return result;
end $$;

create function public.link_catalog_source_product(p_actor_id uuid,p_source_id uuid,p_product_id uuid) returns void
language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();
begin
 if p_actor_id is distinct from actor then raise exception 'Staff session changed' using errcode='42501';end if;
 perform 1 from public.catalog_source_items where id=p_source_id for share;
 if not found then raise exception 'Source catalog row not found' using errcode='23514';end if;
 perform 1 from public.catalog_products where id=p_product_id for share;
 if not found then raise exception 'Catalog product not found' using errcode='23514';end if;
 insert into public.catalog_source_products(source_id,product_id,created_by) values(p_source_id,p_product_id,actor) on conflict do nothing;
end $$;
revoke all on function public.search_catalog_source_items(text),public.configure_catalog_source_item(uuid,uuid,uuid,text,text,text,text,bigint),public.link_catalog_source_product(uuid,uuid,uuid) from public,anon,service_role;
grant execute on function public.search_catalog_source_items(text),public.configure_catalog_source_item(uuid,uuid,uuid,text,text,text,text,bigint),public.link_catalog_source_product(uuid,uuid,uuid) to authenticated;

